package org.sleepwell.app;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;

/** Separate explicit consent for future recorded nights. Saving never exports existing history. */
public final class AutoCalendarActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private final Handler main=new Handler(Looper.getMainLooper());
 private AutoCalendar.Config saved;private List<CalendarEventWrites.Calendar> calendars=List.of();
 private List<AutoCalendar.Item> receipts=List.of();private boolean enabled,busy,resumed,restoreDraft;
 private long selected;private int generation;private String error="",status="",operation;private Bundle pending;
 @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);pending=state;operation=state==null?null:state.getString("operation");if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);render();}
 private void load(){if(operation!=null){observeSave();return;}int mine=++generation;busy=true;render();Context app=getApplicationContext();worker.execute(()->{AutoCalendar.Config config=null;List<CalendarEventWrites.Calendar> choices=List.of();List<AutoCalendar.Item> items=List.of();String failure="",notice="";try{config=AutoCalendar.load(app);items=AutoCalendar.items(app);notice=AutoCalendar.status(app);if(CalendarEventWrites.allowed(app))choices=CalendarEventWrites.factory.open(app).calendars();}catch(RuntimeException failed){failure="Calendar configuration could not be read. Allow access or retry.";}AutoCalendar.Config found=config;List<CalendarEventWrites.Calendar> available=choices;List<AutoCalendar.Item> recent=items;String issue=failure,message=notice;main.post(()->{if(isDestroyed()||mine!=generation)return;busy=false;saved=found;calendars=available;receipts=recent;status=message;error=issue;if(found!=null&&!restoreDraft){enabled=found.enabled;selected=found.calendar;}if(pending!=null){enabled=pending.getBoolean("enabled",enabled);selected=pending.getLong("calendar",selected);long revision=pending.getLong("revision",found==null?0:found.revision);if(found!=null&&revision!=found.revision){enabled=found.enabled;selected=found.calendar;error="Saved consent changed while this page was closed. Review it again.";}pending=null;}restoreDraft=false;render();});});}
 private CalendarEventWrites.Calendar chosen(){for(CalendarEventWrites.Calendar c:calendars)if(c.id==selected)return c;return null;}
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Automatic calendar",this::back);Design.space(body,14);Design.text(body,"Save future completed nights",22,600,Design.INK);Design.space(body,10);Design.text(body,"Off by default. A new recording must start after you enable this setting. Existing history, imports and interrupted nights are not exported.",14,400,Design.MUTED);Design.space(body,14);
  Switch toggle=Design.toggle(body,"Save new recorded nights","One local calendar event per completed night",enabled,on->enabled=on);toggle.setEnabled(!busy&&saved!=null);
  if(!CalendarEventWrites.allowed(this)){Design.space(body,10);Design.button(body,"Allow calendar read and write access",false,this::permission).setEnabled(!busy);Design.text(body,"Nothing is exported when access is granted. You still choose a destination and explicitly Save this consent.",12,400,Design.MUTED);}
  if(!CalendarEventWrites.allowed(this)&&getPreferences(MODE_PRIVATE).getBoolean("asked",false))PlanActivity.detail(body,"settings","App permissions","If Android no longer shows the permission prompt",null,()->{try{startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.fromParts("package",getPackageName(),null)));}catch(RuntimeException missing){error="Open SleepWell's permissions from Android Settings.";render();}});
  CalendarEventWrites.Calendar destination=chosen();PlanActivity.detail(body,"calendar","Destination",destination==null?saved!=null&&!saved.name.isEmpty()?saved.name+" · reload to verify":"Choose a writable calendar":destination.name,null,this::choose);
  Design.space(body,12);Design.text(body,"Shared fields",16,600,Design.INK);Design.space(body,6);Design.text(body,"Fixed title “Sleep period”, original completed start/end and recorded time zone. No note, tags, rating, audio or measurements. Events include the full recording period, including pauses and awake time.",13,400,Design.MUTED);Design.space(body,8);Design.text(body,"Your calendar app controls server sync and sharing. Off stops future work; events already written remain. An in-flight provider write may finish. Uncertain outcomes require receipt review and are not automatically inserted again.",13,400,Design.MUTED);
  if(!status.isEmpty()){Design.space(body,16);Design.text(body,status,13,500,Design.MUTED);}if(!error.isEmpty()){Design.space(body,12);Design.text(body,error,13,500,Design.BROWN);}
  int count=0;for(int n=receipts.size()-1;n>=0&&count<8;n--,count++){AutoCalendar.Item item=receipts.get(n);Design.space(body,12);String label=switch(item.state){case "VERIFIED"->"Saved locally";case "QUEUED"->"Waiting for Android";case "RUNNING"->"Provider work in progress";case "CANCELLED"->"Consent changed";default->"Needs receipt review";};PlanActivity.detail(body,"file",label,RecordUi.date(item.end,java.time.ZoneId.systemDefault()),null,()->startActivity(RecordUi.intent(this,CalendarEventDirectActivity.class).putExtra("record",item.record)));if(!item.issue.isEmpty())Design.text(body,item.issue,12,400,Design.MUTED);}
  Design.space(body,16);Design.button(body,"Reload status and calendars",false,()->{restoreDraft=true;AutoCalendar.resume(this);load();}).setEnabled(!busy);LinearLayout footer=RecordUi.footer(body);Design.button(footer,busy?"Working…":"Save automatic calendar settings",true,this::confirm).setEnabled(!busy&&saved!=null&&(!enabled||destination!=null));Design.button(footer,"Cancel",false,this::back).setEnabled(operation==null);
 }
 private void choose(){if(busy)return;if(calendars.isEmpty()){error=CalendarEventWrites.allowed(this)?"No writable calendar is available. Add one in your calendar app and reload.":"Allow calendar access first.";render();return;}String[] names=calendars.stream().map(c->c.name).toArray(String[]::new);SleepPicker.choices(this,"Writable calendar",names,-1,index->{selected=calendars.get(index).id;error="";render();});}
 private void permission(){if(!resumed||!hasWindowFocus()||busy)return;getPreferences(MODE_PRIVATE).edit().putBoolean("asked",true).apply();requestPermissions(new String[]{Manifest.permission.READ_CALENDAR,Manifest.permission.WRITE_CALENDAR},842);}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==842){restoreDraft=true;load();}}
 private Dialog confirmation;
 private void confirm(){if(!resumed||!hasWindowFocus()||busy||saved==null||confirmation!=null)return;if(!enabled){save(false,null);return;}CalendarEventWrites.Calendar destination=chosen();if(destination==null)return;Dialog dialog=new Dialog(this);confirmation=dialog;dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout content=Design.col(this);Design.pad(content,22,22);content.setBackground(Design.shape(this,Design.CREAM,24));Design.text(content,"Enable future-night exports?",22,600,Design.INK);Design.space(content,14);Design.text(content,destination.name,17,600,Design.INK);Design.space(content,10);Design.text(content,"New recordings started after Save may create one Sleep period event. Start, end and recorded time zone are shared; notes and audio stay out. Existing history is not exported. Your calendar app controls sharing and server sync.",14,400,Design.MUTED);Design.space(content,14);Design.button(content,"Enable for future nights",true,()->{if(!resumed||!dialog.getWindow().getDecorView().hasWindowFocus())return;dialog.dismiss();save(true,destination);});Design.button(content,"Cancel",false,dialog::dismiss);ScrollView scroll=new ScrollView(this);scroll.addView(content);dialog.setContentView(scroll);dialog.setOnDismissListener(d->confirmation=null);dialog.show();Window window=dialog.getWindow();window.setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-Design.dp(this,32),Design.dp(this,440)),-2);androidx.core.view.WindowInsetsControllerCompat bars=androidx.core.view.WindowCompat.getInsetsController(window,window.getDecorView());bars.setAppearanceLightStatusBars(true);bars.setAppearanceLightNavigationBars(true);}

 private void save(boolean on,CalendarEventWrites.Calendar destination){if(!resumed||operation!=null||saved==null)return;long revision=saved.revision;operation=UUID.randomUUID().toString();String request=operation;busy=true;error="";PlanOperations.start(this,request,app->{AutoCalendar.save(app,on,destination,revision);return on?"Enabled for future recordings. Existing history was not exported.":"Automatic calendar export is off.";});render();observeSave();}
 private final Runnable poll=this::observeSave;
 private void observeSave(){if(!resumed||operation==null)return;String token=operation;PlanOperations.Operation run=PlanOperations.start(this,token,app->{throw new IllegalStateException("The settings operation was interrupted. Review consent and Save again; nothing restarts automatically.");});if(!run.done){main.removeCallbacks(poll);main.postDelayed(poll,150);return;}PlanOperations.forget(token);operation=null;busy=false;if(run.error!=null){error=run.error;render();}else{restoreDraft=false;load();}}
 private void back(){if(operation!=null)return;finish();}
 @Override protected void onResume(){super.onResume();resumed=true;if(operation!=null)observeSave();else{AutoCalendar.resume(this);load();}}
 @Override protected void onPause(){resumed=false;main.removeCallbacks(poll);super.onPause();}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putBoolean("enabled",enabled);b.putLong("calendar",selected);if(saved!=null)b.putLong("revision",saved.revision);b.putString("operation",operation);}
 @Override protected void onDestroy(){generation++;if(confirmation!=null)confirmation.dismiss();main.removeCallbacksAndMessages(null);worker.shutdownNow();super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
